+        ref={inputRef}
+      />
+      {helperText && (
+        <p id={helperId} className="helper-text">{helperText}</p>
+      )}
+    </div>
+  );
+}
+
+function ContactForm() {
+  const [values, setValues] = useState({ fullName: "", email: "", phone: "" });
+  const [status, setStatus] = useState("");
