      const firstInvalid = formRef.current.querySelector(":invalid");
      if (firstInvalid) firstInvalid.focus();
      return;
    }
    setStatus(`Thanks, ${values.fullName}. Your message has been received — we'll be in touch shortly.`);
    setValues({ fullName: "", email: "", phone: "" });
  };

  return (
    <section className="card" aria-labelledby="form-title">
      <h2 id="form-title">Contact support</h2>
      <p className="lede">Send us a message and a support specialist will reach out.</p>
      <form ref={formRef} onSubmit={handleSubmit} noValidate={false} aria-describedby="required-note">
        <p id="required-note" className="helper-text" style={{ marginTop: 0, marginBottom: "1rem" }}>
